attr_reader :site, :content, :data_index

def initialize(site, in_source_dir: nil)
  @site = site
  @content = {}
  @entry_filter = EntryFilter.new(site)
  @in_source_dir = in_source_dir || @site.method(:in_source_dir)
  @source_dir = @in_source_dir.call("/")
  # Maps the key-path of each data entry to the path of the file or
  # directory that provides it.
  @data_index = {}
end

