input.newString:
def read_data
  reader = DataReader.new(site)
  @site.data = reader.read(site.config["data_dir"])
  @site.data_file_index = reader.data_index
  return unless site.theme&.data_path

  theme_reader = DataReader.new(
    site,
    :in_source_dir => site.method(:in_theme_dir)
  ).read(site.theme.data_path)
  theme_data = theme_reader.read(site.theme.data_path)
  @site.data = Jekyll::Utils.deep_merge_hashes(theme_data, @site.data)
  @site.data_file_index = Jekyll::Utils.deep_merge_hashes(
    theme_reader.data_index, reader.data_index
  )
end

